<div style="display:flex;justify-content:space-between"><div><h1 class="h"><?=View::e($customer['company_name']?:trim(($customer['first_name']??'').' '.($customer['last_name']??'')))?></h1><div class="sub">IČO <?=View::e($customer['ico'])?> · <?=View::e($customer['email'])?> · <?=View::e($customer['phone'])?></div><div class="card" style="margin-top:16px"><h3>Komunikace / historie</h3><form class="form" method="post" action="/customers/<?=$customer['id']?>/communication"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><input name="subject" placeholder="Předmět"><select name="channel"><option>note</option><option>email</option><option>phone</option><option>meeting</option></select></div><textarea name="message" placeholder="Poznámka / komunikace"></textarea><button class="btn">Uložit do historie</button></form></div></div><a class="btn" href="/customers/<?=$customer['id']?>/edit">Upravit</a></div><div class="grid"><div class="card"><h3>Doklady</h3><?php foreach($documents as $d):?><p><a href="/documents/<?=$d['id']?>/pdf"><b><?=View::e($d['doc_number'])?></b></a> · <?=View::money($d['total_with_vat'])?> · <?=View::e($d['payment_status'])?></p><?php endforeach;?></div><div class="card"><h3>Zakázky</h3><?php foreach($jobs as $j):?><p><a href="/jobs/<?=$j['id']?>"><b><?=View::e($j['name'])?></b></a> · <?=View::money($j['actual_cost'])?></p><?php endforeach;?></div><div class="card"><h3>Výdaje</h3><?php foreach($expenses as $e):?><p><?=View::e($e['supplier'])?> · <?=View::money($e['amount'])?></p><?php endforeach;?></div></div>